index 0130a696887..5a99ab97fce 100644
--- a/src/Columns/ColumnSparse.cpp
+++ b/src/Columns/ColumnSparse.cpp
@@ -544,11 +544,40 @@ ColumnPtr ColumnSparse::indexImpl(const PaddedPODArray<Type> & indexes, size_t l
         return res;
     }

+    /// The indexes are exactly the rows of the non-default values, in order: this is what a sparse filter
+    /// (e.g. `WHERE s != ''`) selects from the column it was computed from. Every row of the result is a value,
+    /// so the result shares the values column.
+    if constexpr (std::is_same_v<Type, UInt64>)
+    {
+        const auto & offsets_data = getOffsetsData();
+        if (limit == offsets_data.size() && memcmp(indexes.data(), offsets_data.data(), limit * sizeof(UInt64)) == 0)
+        {
+            auto res_offsets = ColumnUInt64::create(limit);
+            auto & res_offsets_data = res_offsets->getData();
+            iota(res_offsets_data.data(), limit, UInt64(0));
+            return ColumnSparse::create(values, std::move(res_offsets), limit);
+        }
+    }
