     auto & res_offsets_data = assert_cast<ColumnUInt64 &>(*res_offsets).getData();
     auto res_values = values->cloneEmpty();
     res_values->insertDefault();

+    /// Single rows whose values are consecutive in `values` are copied together with one `insertRangeFrom`
+    /// instead of one virtual `insertFrom` per row. Nothing is pending when `pending_begin == pending_end`.
+    size_t pending_begin = 0;
+    size_t pending_end = 0;
